/**
 * @file cxa_guards.hpp
 * @brief Guards for thread-safe initialization of function-local statics.
 *
 * Deviation from the Itanium C++ ABI: the guards are NOT thread safe. They are
 * a single flag, which is enough while the code that uses them runs on one
 * thread at a time (kernel, or a process with one thread).
 */
#ifndef CXA_GUARDS_HPP
#define CXA_GUARDS_HPP
#include <stdint.h>

extern "C" {

/**
 * @brief Starts the initialization of a local static.
 * @param guard_object Guard storage generated by the compiler, zero at start.
 * @return 1 when the caller must run the initializer, 0 when it is done.
 */
int __cxa_guard_acquire(uint64_t *guard_object);

/**
 * @brief Marks the initialization as finished.
 * @param guard_object Guard acquired earlier; set to 1.
 */
void __cxa_guard_release(uint64_t *guard_object);

/**
 * @brief Called when the initializer throws. Exceptions are disabled, so it does nothing.
 * @param guard_object Guard acquired earlier; unchanged.
 */
void __cxa_guard_abort(uint64_t *guard_object);

}

#endif // !CXA_GUARDS_HPP
